function moveThing(target)
{
   return this.mover.movething(target);
}
function delivery(sourse, target)
{
   target.name = sourse.name;
   target.type = sourse.type;
   target.number = sourse.number;
   target.salePrice = sourse.salePrice;
   if(sourse.type == "头盔" || sourse.type == "衣服" || sourse.type == "武器" || sourse.type == "鞋")
   {
      target.grade = sourse.grade;
      target.vocational = sourse.vocational;
      target.levels = sourse.levels;
      target.mhdj = sourse.mhdj;
      target.minAttack = sourse.minAttack;
      target.maxAttack = sourse.maxAttack;
      target.defense = sourse.defense;
      target.mMinAttack = sourse.mMinAttack;
      target.mMaxAttack = sourse.mMaxAttack;
      target.mDefense = sourse.mDefense;
      target.holes = sourse.holes;
      target.hole1 = sourse.hole1;
      target.hole2 = sourse.hole2;
      target.hole3 = sourse.hole3;
      target.gem1 = sourse.gem1;
      target.gem2 = sourse.gem2;
      target.gem3 = sourse.gem3;
      target.gem11 = sourse.gem11;
      target.gem12 = sourse.gem12;
      target.gem13 = sourse.gem13;
      target.additional = sourse.additional;
      target.spirit = sourse.spirit;
      target.spiritVal = sourse.spiritVal;
      target.spiritLevels = sourse.spiritLevels;
      target.spiritExp = sourse.spiritExp;
      target.element = sourse.element;
      target.wind = sourse.wind;
      target.fire = sourse.fire;
      target.soil = sourse.soil;
      target.water = sourse.water;
      target.val1 = sourse.val1;
      target.val2 = sourse.val2;
      return true;
   }
   if(sourse.type == "幸运符")
   {
      target.grade = sourse.grade;
      target.luckLevels = sourse.luckLevels;
      target.loveName = sourse.loveName;
      target.isFirstLove = sourse.isFirstLove;
      target.moreExp = sourse.moreExp;
      target.moreLife = sourse.moreLife;
      target.moreMp = sourse.moreMp;
      target.moreDefense = sourse.moreDefense;
      target.moreAttack = sourse.moreAttack;
      target.resumeLife = sourse.resumeLife;
      return true;
   }
   if(sourse.type == "戒指")
   {
      target.grade = sourse.grade;
      target.mhdj = sourse.mhdj;
      target.mainType1 = sourse.mainType1;
      target.mainType2 = sourse.mainType2;
      target.pairType1 = sourse.pairType1;
      target.pairType2 = sourse.pairType2;
      target.pairType3 = sourse.pairType3;
      target.pairType4 = sourse.pairType4;
      target.moreAttack = sourse.moreAttack;
      target.moreDefense = sourse.moreDefense;
      target.moreLife = sourse.moreLife;
      target.moreMp = sourse.moreMp;
      target.attack = sourse.attack;
      target.defense = sourse.defense;
      target.maxLife = sourse.maxLife;
      target.maxMp = sourse.maxMp;
      target.otherFire = sourse.otherFire;
      target.reduceDamage = sourse.reduceDamage;
      target.burst = sourse.burst;
      target.jook = sourse.jook;
      return true;
   }
   if(target.type == "庇护铃铛" || target.type == "翡翠铃铛" || target.type == "凤翼铃铛")
   {
      target.grade = sourse.grade;
      target.attributeType1 = sourse.attributeType1;
      target.attributeVal1 = sourse.attributeVal1;
      target.attributeType2 = sourse.attributeType2;
      target.attributeVal2 = sourse.attributeVal2;
      target.attributeType3 = sourse.attributeType3;
      target.attributeVal3 = sourse.attributeVal3;
      target.skill = sourse.skill;
      target.pure = sourse.pure;
      return true;
   }
   if(target.type == "技能图标")
   {
      target.skill = sourse.skill;
      target.salePrice = 0;
      return true;
   }
   if(target.type == "技能书")
   {
      target.vocational = sourse.vocational;
      target.levels = sourse.levels;
      return true;
   }
   if(target.type == "宝石")
   {
      target.val1 = sourse.val1;
      target.val2 = sourse.val2;
      return true;
   }
   if(target.type == "药品")
   {
      target.hpVal = sourse.hpVal;
      target.mpVal = sourse.mpVal;
   }
   return true;
}
this.movingHuanShou = function(target)
{
   this.移动的幻兽蛋.movingHuanShou(target);
};
this.showDetail = function(toX, toY, line, row, htmlText)
{
   this.detail.showDetail(toX,toY,line,row,htmlText);
};
this.hideDetail = function()
{
   this.detail.hideDetail();
};
this.移动的幻兽蛋.huanShou = null;
this.移动的幻兽蛋.movingHuanShou = function(target)
{
   if(target.type)
   {
      this.huanShou = target;
      this._x = _xmouse;
      this._y = _ymouse;
      startDrag(this,1);
      this._visible = true;
      return true;
   }
   return false;
};
this.移动的幻兽蛋.onPress = function(target)
{
   var _loc2_;
   _loc2_ = this._parent.allHuanShouBag.length - 1;
   while(_loc2_ >= 0)
   {
      if(true == this._parent.allHuanShouBag[_loc2_].hitTest(this) && true == this._parent.allHuanShouBag[_loc2_].setHuanShou(this.huanShou))
      {
         stopDrag();
         this._visible = false;
         return true;
      }
      _loc2_ = _loc2_ - 1;
   }
   stopDrag();
   this._visible = false;
   return false;
};
this.detail.txt.html = true;
this.detail.txt.multiline = false;
this.detail.showDetail = function(toX, toY, line, row, htmlText)
{
   var _loc2_ = 2 + 15 * line;
   var _loc3_ = 3.5 + 14 * row;
   this.back._height = _loc2_;
   this.back._width = _loc3_;
   this.txt._height = _loc2_ + 8;
   this.txt._width = _loc3_;
   if(toX + _loc3_ > Stage.width)
   {
      toX -= _loc3_;
   }
   if(toY + _loc2_ > Stage.height)
   {
      toY -= _loc2_;
   }
   this._x = toX;
   this._y = toY;
   this.txt.htmlText = htmlText;
   this._visible = true;
};
this.detail.hideDetail = function()
{
   this._x = 800;
   this._y = 600;
   this._visible = false;
};
this.useItem = function(item)
{
   if(item.type == "空格")
   {
      return false;
   }
   if(item.hitTest(this.backPack) == false && item.hitTest(this.fastKey) == false)
   {
      if(true == this.backPack.isOpen && true == this.backPack.setThing(item))
      {
         item.setThing({type:"空格"});
         return true;
      }
      return false;
   }
   if(item.type == "头盔" || item.type == "衣服" || item.type == "武器" || item.type == "鞋" || item.type == "幸运符" || item.type == "戒指")
   {
      if(this.equipment.setThing(item))
      {
         item.setThing({type:"空格"});
         return true;
      }
      return false;
   }
   if(item.type == "庇护铃铛" || item.type == "翡翠铃铛" || item.type == "凤翼铃铛")
   {
      i = 1;
      while(i <= 3)
      {
         if(this["huanShouItem" + i].isOpen && "空格" == this["huanShouItem" + i].bell.type && this["huanShouItem" + i].setThing(item))
         {
            item.setThing({type:"空格"});
            return true;
         }
         i++;
      }
      return false;
   }
   var _loc5_;
   var _loc0_;
   var _loc10_;
   var _loc9_;
   var _loc8_;
   var _loc7_;
   var _loc11_;
   var _loc6_;
   var _loc13_;
   var _loc12_;
   var _loc14_;
