               this.createThing({type:"紫水晶"});
               _global.sysMsg.addMsg("挖到了 紫水晶");
            }
            else
            {
               this.createThing({type:"陨铁矿"});
               _global.sysMsg.addMsg("挖到了 陨铁矿");
            }
            item.setThing({type:"空格"});
            return true;
         }
         _global.msg.open("\r\r什么也没挖到!\r请在矿洞里使用");
         return false;
         break;
      case "月光礼包":
         this.createThing({type:"宝石",name:"初级月光宝盒"});
         item.setThing({type:"空格"});
         return true;
