   if(target.type == "头盔" || target.type == "衣服" || target.type == "武器" || target.type == "鞋" || target.type == "幸运符" || target.type == "戒指")
   {
      if(target.type == "幸运符")
      {
         if(target.loveName != this._parent.friend.lover.name)
         {
            _global.msg.open("\r\r该幸运符对你是无效，请使用刻有你的恋人名字的幸运符。");
            return false;
         }
      }
      else if(target.type != "戒指")
      {
         if(target.levels > this.role.levels || target.vocational != this.role.vocational)
         {
            return false;
         }
      }
      if("空格" == this[target.type].type)
      {
         this[target.type].setThing(target);
      }
      else
      {
         this._parent.backPack.setThing(this[target.type]);
         this[target.type].setThing(target);
      }
      this.flashAttribute();
      return true;
   }
   return false;
};
