this.make.useGem = function(useNme)
{
   if(isNaN(useNme))
   {
      useNme = 1;
   }
   var _loc3_ = useNme;
   if(this.stone.number > 0)
   {
      if(this.stone.number >= _loc3_)
      {
         this.stone.number -= _loc3_;
         if(this.stone.number == 0)
         {
            this.stone.setThing({type:"空格"});
         }
         return true;
      }
      _global.sysMsg.addMsg("宝石数量不足！");
      return false;
   }
   if(_loc3_ == 1)
   {
      this.stone.setThing({type:"空格"});
      return true;
   }
   return false;
};
